WITH subq1 AS ( WITH inner_cte AS ( SELECT aca.ACADEMIC_YEAR, aca.ACADEMIC_YEAR_DESC, sub.DEPARTMENT_NAME, STDDEV(sub.TOTAL_UNITS)/NULLIF(AVG(sub.TOTAL_UNITS),0) AS coefficient_of_variation FROM COURSE_CATALOG_SUBJECT_OFFERED sub JOIN ACADEMIC_TERMS_ALL aca ON sub.TERM_CODE = aca.TERM_CODE JOIN ACADEMIC_TERM_PARAMETER param ON aca.TERM_CODE = param.TERM_CODE WHERE param.IS_CURRENT_TERM = 'Y' AND sub.TOTAL_UNITS > 0 GROUP BY aca.ACADEMIC_YEAR, aca.ACADEMIC_YEAR_DESC, sub.DEPARTMENT_NAME HAVING AVG(sub.TOTAL_UNITS) > 0 ) SELECT ACADEMIC_YEAR, ACADEMIC_YEAR_DESC, DEPARTMENT_NAME, SUM(coefficient_of_variation) AS total_coefficient_of_variation FROM inner_cte GROUP BY ACADEMIC_YEAR, ACADEMIC_YEAR_DESC, DEPARTMENT_NAME WITH ROLLUP HAVING SUM(coefficient_of_variation) > 0 ), subq2 AS ( WITH inner_cte AS ( SELECT sd.DEPARTMENT_NAME, sd.DEPARTMENT_CODE, MAX(ccc.TOTAL_UNITS) - MIN(ccc.TOTAL_UNITS) AS total_units_range, VARIANCE(ccc.TOTAL_UNITS) AS total_units_variance, AVG(ccc.TOTAL_UNITS) AS avg_total_units FROM SIS_DEPARTMENT sd JOIN CIS_COURSE_CATALOG ccc ON sd.DEPARTMENT_CODE = ccc.DEPARTMENT_CODE WHERE sd.IS_DEGREE_GRANTING = 'Y' AND ccc.ACADEMIC_YEAR = 2008 AND sd.DEPARTMENT_CODE <> '5' GROUP BY sd.DEPARTMENT_NAME, sd.DEPARTMENT_CODE ) SELECT ic.DEPARTMENT_NAME, ic.DEPARTMENT_CODE, ic.avg_total_units, ic.total_units_range, ic.total_units_variance FROM inner_cte ic WHERE ic.avg_total_units = ( SELECT MAX(avg_total_units) FROM inner_cte ) ) SELECT s1.ACADEMIC_YEAR, s1.ACADEMIC_YEAR_DESC, s1.DEPARTMENT_NAME, s1.total_coefficient_of_variation, s2.avg_total_units, s2.total_units_range, s2.total_units_variance FROM subq1 s1 LEFT JOIN subq2 s2 ON s1.DEPARTMENT_NAME = s2.DEPARTMENT_NAME ORDER BY s1.ACADEMIC_YEAR, s1.DEPARTMENT_NAME ;